const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const nePacific = ee.Geometry.Polygon([
    [[-180, 30], [-120, 30], [-120, 60], [-180, 60], [-180, 30]]
  ]);

  // 2. Data Acquisition
  const sstCol = ee.ImageCollection('NOAA/CDR/OISST/V2_1').select('sst');

  // Baseline: August months 1985-2012
  const baselineFilter = ee.Filter.and(
    ee.Filter.calendarRange(1985, 2012, 'year'),
    ee.Filter.calendarRange(8, 8, 'month')
  );
  const baselineCol = sstCol.filter(baselineFilter);

  // Comparison: August 2019
  const aug2019Col = sstCol.filterDate('2019-08-01', '2019-09-01');

  // Check data availability
  const baselineSize = baselineCol.size().getInfo();
  const aug2019Size = aug2019Col.size().getInfo();

  console.log(`Baseline images (1985-2012 Aug): ${baselineSize}`);
  console.log(`2019 August images: ${aug2019Size}`);

  if (baselineSize === 0 || aug2019Size === 0) {
    console.log("<answer>C1</answer>");
    return;
  }

  // 3. Processing - Calculate baseline climatology
  const baselineMean = baselineCol.mean();

  // Get 2019 August mean
  const aug2019Mean = aug2019Col.mean();

  // 4. Calculate regional means
  const baselineStats = baselineMean.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: nePacific,
    scale: 25000,
    maxPixels: 1e9
  });

  const aug2019Stats = aug2019Mean.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: nePacific,
    scale: 25000,
    maxPixels: 1e9
  });

  const baselineSST = baselineStats.get('sst').getInfo();
  const aug2019SST = aug2019Stats.get('sst').getInfo();

  // Check for valid pixels
  if (baselineSST === null || aug2019SST === null) {
    console.log("No valid SST values retrieved");
    console.log("<answer>C2</answer>");
    return;
  }

  // Validate temperature range (reasonable SST values)
  if (baselineSST < -2 || baselineSST > 35 || aug2019SST < -2 || aug2019SST > 35) {
    console.log(`Invalid SST values: baseline=${baselineSST}, 2019=${aug2019SST}`);
    console.log("<answer>C3</answer>");
    return;
  }

  // 5. Comparison and final answer
  console.log(`Baseline SST (1985-2012 Aug): ${baselineSST.toFixed(2)}°C`);
  console.log(`2019 August SST: ${aug2019SST.toFixed(2)}°C`);
  console.log(`Difference: ${(aug2019SST - baselineSST).toFixed(2)}°C`);

  if (aug2019SST < baselineSST) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
